def lexical_entries(language):
    entries, glosses = build_entries(language, PLACES | PEOPLE, SENSES, set(PLACES))
    entry = entries["gallowglass_soldier"]
    entry["form"] = " ".join(language.lexicon[key]["form"] for key in entry["derivationKeys"])
    entry["roman"] = language.reading(entry["form"])
    entries["walter_whitmore"]["origin"] = "Theatrical name adaptation using the native water root and a final r. The resemblance carries the spoken prophecy and differs from Sir Walter Blunt's established form."
    regular = language.lexicon["therefore"]["form"]
    assert regular.startswith("ho"), regular
    form = "ha" + regular[2:]
    entries["argo_therefore_jest"] = dict(form=form, roman=language.reading(form),
        pos="adverb", semanticId="lex.argo_therefore_jest", usageScope="editorial-exception",
        meaning="Bevis's affected mispronunciation of therefore, in his comment about the weaver spinning the enemies' thread of life.",
        origin="A changed first vowel in the native therefore, matching Bevis's argo for Latin ergo.",
        derivationKeys=["therefore"], status="authored", historicalForms=[])
    glosses["argo_therefore_jest"] = "therefore (distorted)"
    return entries, glosses


def prepare():
    add_source_entries("henry-vi-part-2", "henry-vi-part-1", lexical_entries,
                       "Salisbury and his son Warwick retain separate identities. Suffolk weds by proxy and relinquishes his claim to Henry.")


if __name__ == "__main__":
    prepare()
